"use client";

import { useState, useEffect } from "react";
import { logger } from '@/lib/logger';
import { useSession } from "next-auth/react";
import { TrendingUp, Award, Clock, Target, CheckCircle, BookOpen, Trophy, Loader2 } from "lucide-react";
import { getUserAggregateProgressAction, calculateStreakAction } from "@/app/actions/academy";
import BackButton from "@/components/ui/BackButton";

export default function ProgressPage() {
    const { data: session } = useSession();
    const [loading, setLoading] = useState(true);
    const [userId, setUserId] = useState<string | null>(null);
    const [progressData, setProgressData] = useState({
        totalCourses: 0,
        completedCourses: 0,
        inProgressCourses: 0,
        totalHoursLearned: 0,
        certificatesEarned: 0,
        currentStreak: 0, // Streak tracking requires activity log collection - can be added post-launch
        totalLessons: 0,
        completedLessons: 0,
        overallProgress: 0,
    });

    useEffect(() => {
        if (session?.user?.id) {
            setUserId(session.user.id);
        }
    }, [session]);

    useEffect(() => {
        async function loadProgress() {
            if (!userId) return;

            setLoading(true);
            try {
                const [data, { streak }] = await Promise.all([
                    getUserAggregateProgressAction(userId),
                    calculateStreakAction(userId),
                ]);
                setProgressData({
                    ...data,
                    currentStreak: streak,
                });
            } catch (error) {
                logger.error("Failed to load progress:", error);
            } finally {
                setLoading(false);
            }
        }

        loadProgress();
    }, [userId]);

    if (loading) {
        return (
            <div className="flex items-center justify-center min-h-[400px]">
                <Loader2 className="w-12 h-12 animate-spin text-blue-600" />
            </div>
        );
    }

    return (
        <div className="space-y-8">
            {/* Header */}
            <div>
                <BackButton fallbackPath="/academy/dashboard" />
                <h1 className="text-3xl font-bold text-slate-900 mb-2">
                    Learning Progress
                </h1>
                <p className="text-slate-600">
                    Track your achievements and learning milestones
                </p>
            </div>

            {/* Overview Stats */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-blue-100 rounded-lg flex items-center justify-center mb-3">
                            <BookOpen className="w-6 h-6 text-blue-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {progressData.totalCourses}
                        </p>
                        <p className="text-sm text-slate-600">Total Courses</p>
                    </div>
                </div>

                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-green-100 rounded-lg flex items-center justify-center mb-3">
                            <CheckCircle className="w-6 h-6 text-green-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {progressData.completedCourses}
                        </p>
                        <p className="text-sm text-slate-600">Completed</p>
                    </div>
                </div>

                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-yellow-100 rounded-lg flex items-center justify-center mb-3">
                            <Award className="w-6 h-6 text-yellow-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {progressData.certificatesEarned}
                        </p>
                        <p className="text-sm text-slate-600">Certificates</p>
                    </div>
                </div>

                <div className="bg-white rounded-xl p-6 border border-slate-200">
                    <div className="flex flex-col items-center text-center">
                        <div className="w-12 h-12 bg-orange-100 rounded-lg flex items-center justify-center mb-3">
                            <Clock className="w-6 h-6 text-orange-600" />
                        </div>
                        <p className="text-2xl font-bold text-slate-900">
                            {Math.round(progressData.totalHoursLearned)}h
                        </p>
                        <p className="text-sm text-slate-600">Learning Time</p>
                    </div>
                </div>
            </div>

            {/* Overall Progress */}
            <div className="bg-white rounded-xl p-6 border border-slate-200">
                <div className="flex items-center justify-between mb-4">
                    <h2 className="text-xl font-bold text-slate-900">Overall Progress</h2>
                    <span className="text-2xl font-bold text-blue-600">{progressData.overallProgress}%</span>
                </div>
                <div className="h-4 bg-slate-200 rounded-full overflow-hidden mb-2">
                    <div
                        className="h-2 bg-linear-to-r from-primary to-blue-500 rounded-full transition-all"
                        style={{ width: `${progressData.overallProgress}%` }}
                    />
                </div>
                <p className="text-sm text-slate-600">
                    {progressData.completedLessons} of {progressData.totalLessons} lessons completed
                </p>
            </div>

            {/* Empty State or Stats */}
            {progressData.totalCourses === 0 ? (
                <div className="bg-white rounded-xl p-12 border border-slate-200 text-center">
                    <div className="w-20 h-20 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-6">
                        <BookOpen className="w-10 h-10 text-slate-400" />
                    </div>
                    <h3 className="text-xl font-semibold text-slate-900 mb-2">
                        No Courses Enrolled
                    </h3>
                    <p className="text-slate-600 mb-6 max-w-md mx-auto">
                        Start your learning journey by enrolling in courses from our Academy catalog
                    </p>
                    <a
                        href="/academy"
                        className="inline-flex items-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-medium rounded-lg transition-colors"
                    >
                        <BookOpen className="w-5 h-5" />
                        Browse Courses
                    </a>
                </div>
            ) : (
                <>
                    {/* Course Stats */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="bg-white rounded-xl p-6 border border-slate-200">
                            <div className="flex items-center gap-3 mb-4">
                                <div className="w-10 h-10 bg-blue-100 rounded-lg flex items-center justify-center">
                                    <TrendingUp className="w-5 h-5 text-blue-600" />
                                </div>
                                <h3 className="font-bold text-slate-900">In Progress</h3>
                            </div>
                            <p className="text-3xl font-bold text-slate-900 mb-1">
                                {progressData.inProgressCourses}
                            </p>
                            <p className="text-sm text-slate-600">
                                Courses currently learning
                            </p>
                        </div>

                        <div className="bg-white rounded-xl p-6 border border-slate-200">
                            <div className="flex items-center gap-3 mb-4">
                                <div className="w-10 h-10 bg-green-100 rounded-lg flex items-center justify-center">
                                    <Trophy className="w-5 h-5 text-green-600" />
                                </div>
                                <h3 className="font-bold text-slate-900">Completion Rate</h3>
                            </div>
                            <p className="text-3xl font-bold text-slate-900 mb-1">
                                {progressData.totalCourses > 0
                                    ? Math.round((progressData.completedCourses / progressData.totalCourses) * 100)
                                    : 0}%
                            </p>
                            <p className="text-sm text-slate-600">
                                {progressData.completedCourses} of {progressData.totalCourses} completed
                            </p>
                        </div>
                    </div>

                    {/* Info Card */}
                    <div className="bg-linear-to-br from-blue-50 to-indigo-50 border border-blue-200 rounded-2xl p-6">
                        <div className="flex gap-4">
                            <div className="w-12 h-12 bg-blue-600 rounded-xl flex items-center justify-center shrink-0">
                                <Target className="w-6 h-6 text-white" />
                            </div>
                            <div>
                                <h4 className="font-semibold text-slate-900 mb-2">
                                    Keep Learning!
                                </h4>
                                <p className="text-sm text-slate-900">
                                    You&apos;re making great progress! Complete lessons to unlock certificates and advance your career in agribusiness.
                                </p>
                            </div>
                        </div>
                    </div>
                </>
            )}
        </div>
    );
}

"use client";

import { useState, useEffect, use } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import {
    ArrowLeft, CheckCircle, XCircle, Loader2, Trophy,
    AlertTriangle, RefreshCw
} from "lucide-react";
import {
    getCourseByIdAction,
    submitQuizScoreAction,
    type Course,
    type CourseModule,
    type Quiz
} from "@/app/actions/academy";
import { useToast } from "@/contexts/ToastContext";

interface QuizPageProps {
    params: Promise<{ courseId: string; moduleId: string }>;
}

export default function QuizPage(props: QuizPageProps) {
    // Next.js 16: params is now a Promise, must unwrap with React.use()
    const params = use(props.params);
    const { courseId, moduleId } = params;

    const router = useRouter();
    const { data: session, status } = useSession();
    const { showToast } = useToast();
    const [course, setCourse] = useState<Course | null>(null);
    const [currentModule, setCurrentModule] = useState<CourseModule | null>(null);
    const [quiz, setQuiz] = useState<Quiz | null>(null);
    const [loading, setLoading] = useState(true);
    const [submitting, setSubmitting] = useState(false);
    const [quizStarted, setQuizStarted] = useState(false);
    const [quizCompleted, setQuizCompleted] = useState(false);
    const [selectedAnswers, setSelectedAnswers] = useState<Record<string, number>>({});
    const [score, setScore] = useState<number | null>(null);
    const [passed, setPassed] = useState<boolean>(false);

    useEffect(() => {
        if (status === "unauthenticated") {
            router.push("/auth/login?callbackUrl=/academy");
            return;
        }
    }, [status, router]);

    useEffect(() => {
        if (status === "authenticated" && session?.user) {
            loadQuiz();
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [status, session, courseId, moduleId]);

    async function loadQuiz() {
        setLoading(true);

        const courseData = await getCourseByIdAction(courseId);

        if (!courseData) {
            setLoading(false);
            return;
        }

        // Find module and quiz
        const module = courseData.modules.find(m => m.id === moduleId);

        setCourse(courseData);
        setCurrentModule(module || null);
        setQuiz(module?.quiz || null);
        setLoading(false);
    }

    function handleSelectAnswer(questionId: string, answerIndex: number) {
        setSelectedAnswers(prev => ({
            ...prev,
            [questionId]: answerIndex
        }));
    }

    async function handleSubmitQuiz() {
        if (!session?.user || !quiz || !currentModule) return;

        // Calculate score
        let correctAnswers = 0;
        quiz.questions.forEach(question => {
            if (selectedAnswers[question.id] === question.correctAnswer) {
                correctAnswers++;
            }
        });

        const percentage = Math.round((correctAnswers / quiz.questions.length) * 100);
        setScore(percentage);

        // Submit to backend
        setSubmitting(true);
        const result = await submitQuizScoreAction(
            session.user.id,
            courseId,
            moduleId,
            percentage
        );

        if (result.success) {
            setPassed(result.passed || false);
            setQuizCompleted(true);
        } else {
            showToast(result.error || "Failed to submit quiz", "error");
        }

        setSubmitting(false);
    }

    function handleRetry() {
        setSelectedAnswers({});
        setScore(null);
        setPassed(false);
        setQuizCompleted(false);
        setQuizStarted(false);
    }

    if (loading || status === "loading") {
        return (
            <div className="min-h-screen bg-linear-to-br from-slate-50 to-blue-50 flex items-center justify-center">
                <Loader2 className="w-12 h-12 text-blue-500 animate-spin" />
            </div>
        );
    }

    if (!course || !currentModule || !quiz) {
        return (
            <div className="min-h-screen bg-linear-to-br from-slate-50 to-blue-50 flex items-center justify-center">
                <div className="text-center">
                    <h2 className="text-2xl font-bold text-slate-900 mb-2">
                        Quiz Not Found
                    </h2>
                    <button
                        onClick={() => router.push(`/academy/${courseId}`)}
                        className="text-blue-500 hover:text-blue-600 font-medium"
                    >
                        ← Back to Course
                    </button>
                </div>
            </div>
        );
    }

    const allQuestionsAnswered = quiz.questions.every(q => selectedAnswers[q.id] !== undefined);

    // Quiz completed screen
    if (quizCompleted && score !== null) {
        return (
            <div className="min-h-screen bg-linear-to-br from-slate-50 to-blue-50 py-12 px-4">
                <div className="max-w-2xl mx-auto">
                    <div className="bg-white rounded-2xl shadow-xl p-8 text-center">
                        {passed ? (
                            <>
                                <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                                    <Trophy className="w-12 h-12 text-green-600" />
                                </div>
                                <h1 className="text-3xl font-bold text-slate-900 mb-3">
                                    Congratulations! 🎉
                                </h1>
                                <p className="text-lg text-slate-600 mb-6">
                                    You passed the quiz!
                                </p>
                            </>
                        ) : (
                            <>
                                <div className="w-20 h-20 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-6">
                                    <XCircle className="w-12 h-12 text-red-600" />
                                </div>
                                <h1 className="text-3xl font-bold text-slate-900 mb-3">
                                    Not Quite There
                                </h1>
                                <p className="text-lg text-slate-600 mb-6">
                                    You need {quiz.passingScore}% to pass. Keep studying!
                                </p>
                            </>
                        )}

                        {/* Score Display */}
                        <div className={`inline-block px-8 py-4 rounded-2xl mb-8 ${passed
                            ? "bg-green-100"
                            : "bg-red-100"
                            }`}>
                            <p className="text-sm font-medium text-slate-600 mb-1">
                                Your Score
                            </p>
                            <p className={`text-5xl font-bold ${passed
                                ? "text-green-600"
                                : "text-red-600"
                                }`}>
                                {score}%
                            </p>
                            <p className="text-xs text-slate-500 mt-1">
                                Passing score: {quiz.passingScore}%
                            </p>
                        </div>

                        {/* Actions */}
                        <div className="flex flex-col gap-3">
                            {!passed && (
                                <button
                                    onClick={handleRetry}
                                    className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-xl transition flex items-center justify-center gap-2"
                                >
                                    <RefreshCw className="w-5 h-5" />
                                    Retry Quiz
                                </button>
                            )}
                            <button
                                onClick={() => router.push(`/academy/${courseId}`)}
                                className="px-6 py-3 bg-slate-200 hover:bg-slate-300 text-slate-900 font-semibold rounded-xl transition"
                            >
                                Back to Course
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        );
    }

    // Quiz start screen
    if (!quizStarted) {
        return (
            <div className="min-h-screen bg-linear-to-br from-slate-50 to-blue-50 py-12 px-4">
                <div className="max-w-2xl mx-auto">
                    <button
                        onClick={() => router.push(`/academy/${courseId}`)}
                        className="mb-6 text-slate-600 hover:text-slate-900 text-sm font-medium flex items-center gap-2"
                    >
                        <ArrowLeft className="w-4 h-4" />
                        Back to Course
                    </button>

                    <div className="bg-white rounded-2xl shadow-xl p-8">
                        <h1 className="text-3xl font-bold text-slate-900 mb-4">
                            {currentModule.title} - Quiz
                        </h1>
                        <p className="text-slate-600 mb-8">
                            Test your knowledge of this module
                        </p>

                        <div className="bg-blue-50 border border-blue-200 rounded-xl p-6 mb-8">
                            <h3 className="font-semibold text-slate-900 mb-4">
                                Quiz Information
                            </h3>
                            <div className="space-y-2 text-sm text-slate-600">
                                <p>📝 <strong>{quiz.questions.length}</strong> questions</p>
                                <p>🎯 Passing score: <strong>{quiz.passingScore}%</strong></p>
                                <p>⏱️ No time limit - take your time</p>
                                <p>🔄 You can retake the quiz if you don't pass</p>
                            </div>
                        </div>

                        <button
                            onClick={() => setQuizStarted(true)}
                            className="w-full px-6 py-4 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-xl transition"
                        >
                            Start Quiz
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    // Quiz questions screen
    return (
        <div className="min-h-screen bg-linear-to-br from-slate-50 to-blue-50 py-12 px-4">
            <div className="max-w-3xl mx-auto">
                <button
                    onClick={() => router.push(`/academy/${courseId}`)}
                    className="mb-6 text-slate-600 hover:text-slate-900 text-sm font-medium flex items-center gap-2"
                >
                    <ArrowLeft className="w-4 h-4" />
                    Back to Course
                </button>

                <div className="bg-white rounded-2xl shadow-xl p-8 mb-6">
                    <div className="flex items-center justify-between mb-6">
                        <h1 className="text-2xl font-bold text-slate-900">
                            {currentModule.title} - Quiz
                        </h1>
                        <div className="text-sm text-slate-600">
                            {Object.keys(selectedAnswers).length} / {quiz.questions.length} answered
                        </div>
                    </div>

                    {/* Questions */}
                    <div className="space-y-8">
                        {quiz.questions.map((question, questionIndex) => (
                            <div key={question.id} className="pb-6 border-b border-slate-200 last:border-0">
                                <p className="font-semibold text-slate-900 mb-4">
                                    <span className="text-blue-600 mr-2">
                                        {questionIndex + 1}.
                                    </span>
                                    {question.question}
                                </p>

                                <div className="space-y-3">
                                    {question.options.map((option, optionIndex) => (
                                        <button
                                            key={optionIndex}
                                            onClick={() => handleSelectAnswer(question.id, optionIndex)}
                                            className={`w-full text-left px-4 py-3 rounded-xl border-2 transition ${selectedAnswers[question.id] === optionIndex
                                                ? "border-blue-500 bg-blue-50"
                                                : "border-slate-200 hover:border-slate-300"
                                                }`}
                                        >
                                            <div className="flex items-center gap-3">
                                                <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${selectedAnswers[question.id] === optionIndex
                                                    ? "border-blue-500 bg-blue-500"
                                                    : "border-slate-300"
                                                    }`}>
                                                    {selectedAnswers[question.id] === optionIndex && (
                                                        <div className="w-2 h-2 bg-white rounded-full" />
                                                    )}
                                                </div>
                                                <span className="text-slate-900">
                                                    {option}
                                                </span>
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Submit Button */}
                {!allQuestionsAnswered && (
                    <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-4 mb-6 flex items-start gap-3">
                        <AlertTriangle className="w-5 h-5 text-yellow-600 shrink-0 mt-0.5" />
                        <p className="text-sm text-yellow-800">
                            Please answer all questions before submitting
                        </p>
                    </div>
                )}

                <button
                    onClick={handleSubmitQuiz}
                    disabled={!allQuestionsAnswered || submitting}
                    className="w-full px-6 py-4 bg-green-600 hover:bg-green-700 disabled:bg-slate-300 disabled:cursor-not-allowed text-white font-semibold rounded-xl transition flex items-center justify-center gap-2"
                >
                    {submitting ? (
                        <>
                            <Loader2 className="w-5 h-5 animate-spin" />
                            <span>Submitting...</span>
                        </>
                    ) : (
                        <>
                            <CheckCircle className="w-5 h-5" />
                            <span>Submit Quiz</span>
                        </>
                    )}
                </button>
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState, useCallback, useRef } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import Link from "next/link";
import { Loader2, CheckCircle, XCircle, PartyPopper, ArrowRight } from "lucide-react";
import { verifyAcademyPaymentAction } from "@/app/actions/academy";
import { Suspense } from "react";

function PaymentCallbackContent() {
    const searchParams = useSearchParams();
    const router = useRouter();
    const reference = searchParams.get("reference") || searchParams.get("trxref");
    const [status, setStatus] = useState<"loading" | "success" | "failed">("loading");
    const [errorDetail, setErrorDetail] = useState<string | null>(null);
    const [countdown, setCountdown] = useState(5);
    // Prevent double-invocation: React Strict Mode fires effects twice in development.
    // Without this guard, verifyAcademyPaymentAction would run twice per page load.
    const hasVerified = useRef(false);

    const verify = useCallback(async () => {
        if (hasVerified.current) return;
        hasVerified.current = true;

        if (!reference) {
            setTimeout(() => setStatus("failed"), 0);
            return;
        }

        try {
            const result = await verifyAcademyPaymentAction(reference);
            if (result.success) {
                setStatus("success");
            } else {
                setErrorDetail((result as any).error || null);
                setStatus("failed");
            }
        } catch (err: any) {
            setErrorDetail(err?.message || "Network error — please try again");
            setStatus("failed");
        }
    }, [reference]);

    useEffect(() => {
        verify();
    }, [verify]);

    // Auto-redirect after success
    useEffect(() => {
        if (status !== "success") return;
        const timer = setInterval(() => {
            setCountdown(prev => {
                if (prev <= 1) {
                    clearInterval(timer);
                    router.push("/academy/setup");
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
        return () => clearInterval(timer);
    }, [status, router]);

    if (status === "loading") {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-50">
                <div className="text-center">
                    <Loader2 className="w-12 h-12 text-blue-600 animate-spin mx-auto mb-4" />
                    <p className="text-slate-600 font-medium">Verifying your payment...</p>
                </div>
            </div>
        );
    }

    if (status === "failed") {
        return (
            <div className="min-h-screen flex items-center justify-center bg-slate-50 px-4">
                <div className="bg-white rounded-3xl shadow-2xl p-8 max-w-md w-full text-center">
                    <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
                        <XCircle className="w-8 h-8 text-red-600" />
                    </div>
                    <h1 className="text-2xl font-bold text-slate-900 mb-2">Payment Verification Failed</h1>
                    <p className="text-slate-600 mb-2">
                        We couldn&apos;t verify your payment. Please try again or contact support.
                    </p>
                    {errorDetail && (
                        <p className="text-sm text-red-600 bg-red-50 border border-red-200 rounded-lg px-4 py-2 mb-4 font-mono break-words">
                            {errorDetail}
                        </p>
                    )}
                    <Link
                        href="/academy/setup"
                        className="inline-flex items-center gap-2 px-6 py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition"
                    >
                        Try Again
                    </Link>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen flex items-center justify-center bg-slate-50 px-4">
