                            <Mail className="w-8 h-8 text-slate-400" />
                        </div>
                        <h3 className="font-bold text-slate-900 mb-1">No broadcasts yet</h3>
                        <p className="text-slate-500 text-sm mb-6">Past broadcasts will appear here once you send one.</p>
