                                    ))}
                                </dl>
                            </div>
                        )}

                        {/* Timeline */}
                        {window.timeline.length > 0 && (
                            <div className="bg-white rounded-2xl p-6 shadow-lg">
                                <h2 className="text-2xl font-bold text-slate-900 mb-6">
