// Helper component for file uploads
function FileUploadField({
    label,
    description,
    file,
    onChange,
    required,
    uploadState
}: {
    label: string;
    description: string;
    file: File | null;
    onChange: (file: File | null) => void;
    required?: boolean;
    uploadState?: { progress: number; isUploading: boolean; error: string | null };
}) {
    const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0] || null;
        onChange(selectedFile);
    };

    return (
        <div>
            <label className="block text-sm font-semibold text-slate-900 mb-2">
                {label} {required && "*"}
            </label>
            <p className="text-sm text-slate-600 mb-3">{description}</p>

            <div className="border-2 border-dashed border-slate-300 rounded-lg p-6 relative">
                {/* Upload Overlay */}
                {uploadState?.isUploading && (
                    <div className="absolute inset-0 bg-white/80 flex items-center justify-center z-10 flex-col">
                        <Loader2 className="w-6 h-6 animate-spin text-green-600 mb-2" />
                        <span className="text-sm font-bold text-green-800">Uploading {Math.round(uploadState.progress)}%</span>
                    </div>
                )}

                {file ? (
                    <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                            <FileText className="w-8 h-8 text-green-600" />
                            <div>
                                <p className="font-semibold text-slate-900">{file.name}</p>
                                <p className="text-sm text-slate-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                            </div>
                        </div>
                        <button
                            type="button"
                            onClick={() => onChange(null)}
                            disabled={uploadState?.isUploading}
                            className="p-2 hover:bg-red-100 rounded-lg transition-colors disabled:opacity-50"
                        >
                            <X className="w-5 h-5 text-red-600" />
                        </button>
                    </div>
                ) : (
                    <label className="flex flex-col items-center cursor-pointer">
                        <Upload className="w-12 h-12 text-slate-400 mb-3" />
                        <p className="text-sm font-semibold text-slate-900 mb-1">
                            Click to upload
                        </p>
                        <p className="text-xs text-slate-500">PDF, JPG, PNG (max 5MB)</p>
                        <input
                            type="file"
                            accept=".pdf,.jpg,.jpeg,.png"
                            onChange={handleFileSelect}
                            className="hidden"
                            required={required}
                        />
                    </label>
                )}
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { logger } from '@/lib/logger';
import dynamic from "next/dynamic";
import { Filter, Grid, MapIcon, Search } from "lucide-react";

// Dynamically import map component to avoid SSR issues
const MapView = dynamic(() => import("@/components/farm-nation/MapView"), {
    ssr: false,
    loading: () => (
        <div className="h-[600px] bg-slate-100 rounded-xl flex items-center justify-center">
            <div className="text-center">
                <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-4" />
                <p className="text-slate-600">Loading map...</p>
            </div>
        </div>
    )
});

type LandListing = {
    id: string;
    title: string;
    category: string;
    state: string;
    lga: string;
    size: number;
    unit: string;
    pricePerUnit: number;
    totalPrice: number;
    gpsCoordinates?: {
        latitude: number;
        longitude: number;
    };
    images: string[];
    verificationStatus: string;
};

type ViewMode = "map" | "grid";

export default function FarmNationMapPage() {
    const router = useRouter();
    const [listings, setListings] = useState<LandListing[]>([]);
    const [filteredListings, setFilteredListings] = useState<LandListing[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [viewMode, setViewMode] = useState<ViewMode>("map");

    const [filters, setFilters] = useState({
        state: "",
        category: "",
        minPrice: 0,
        maxPrice: 0,
        minSize: 0,
        maxSize: 0,
    });

    const [searchQuery, setSearchQuery] = useState("");

    const landCategories = [
        { value: "farmland", label: "Farmland", icon: "🌾" },
        { value: "ranch", label: "Ranch/Pasture", icon: "🐄" },
        { value: "forest", label: "Forest Land", icon: "🌲" },
        { value: "mixed", label: "Mixed-Use", icon: "🌻" },
        { value: "orchard", label: "Orchard", icon: "🍊" },
        { value: "aquaculture", label: "Aquaculture", icon: "🐟" }
    ];

    const nigerianStates = [
        "Abia", "Adamawa", "Akwa Ibom", "Anambra", "Bauchi", "Bayelsa", "Benue", "Borno",
        "Cross River", "Delta", "Ebonyi", "Edo", "Ekiti", "Enugu", "Gombe", "Imo",
        "Jigawa", "Kaduna", "Kano", "Katsina", "Kebbi", "Kogi", "Kwara", "Lagos",
        "Nasarawa", "Niger", "Ogun", "Ondo", "Osun", "Oyo", "Plateau", "Rivers",
        "Sokoto", "Taraba", "Yobe", "Zamfara", "FCT"
    ];

    useEffect(() => {
        fetchListings();
    }, []);

    useEffect(() => {
        applyFilters();
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [listings, filters, searchQuery]);

    async function fetchListings() {
        setIsLoading(true);
        try {
            const response = await fetch("/api/farm-nation/listings");
            const data = await response.json();

            if (data.success) {
                // Only show verified listings with GPS coordinates on the map
                const mappableListings = data.listings.filter(
                    (l: LandListing) => l.verificationStatus === "verified" && l.gpsCoordinates
                );
                setListings(mappableListings);
            }
        } catch (error) {
            logger.error("Failed to fetch listings:", error);
        } finally {
            setIsLoading(false);
        }
    };

    function applyFilters() {
        let filtered = listings;

        if (filters.state) {
            filtered = filtered.filter(l => l.state === filters.state);
        }

        if (filters.category) {
            filtered = filtered.filter(l => l.category === filters.category);
        }

        if (filters.minPrice > 0) {
            filtered = filtered.filter(l => l.totalPrice >= filters.minPrice);
        }

        if (filters.maxPrice > 0) {
            filtered = filtered.filter(l => l.totalPrice <= filters.maxPrice);
        }

        if (filters.minSize > 0) {
            filtered = filtered.filter(l => l.size >= filters.minSize);
        }

        if (filters.maxSize > 0) {
            filtered = filtered.filter(l => l.size <= filters.maxSize);
        }

        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            filtered = filtered.filter(l =>
                l.title?.toLowerCase().includes(query) ||
                l.state?.toLowerCase().includes(query) ||
                l.lga?.toLowerCase().includes(query)
            );
        }

        setFilteredListings(filtered);
    };

    function resetFilters() {
        setFilters({
            state: "",
            category: "",
            minPrice: 0,
            maxPrice: 0,
            minSize: 0,
            maxSize: 0,
        });
        setSearchQuery("");
    };

    return (
        <div className="min-h-screen bg-slate-50 py-8">
            <div className="max-w-7xl mx-auto px-4">
                <div className="mb-8">
                    <h1 className="text-3xl font-bold text-slate-900 mb-2">
                        Explore Land Listings
                    </h1>
                    <p className="text-slate-600">
                        Discover verified agricultural land across Nigeria
                    </p>
                </div>

                {/* Filters */}
                <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
                    <div className="flex items-center gap-2 mb-4">
                        <Filter className="w-5 h-5 text-primary" />
                        <h2 className="text-lg font-bold text-slate-900">Filters</h2>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-4">
                        <div>
                            <label className="block text-sm font-semibold text-slate-900 mb-2">
                                Search
                            </label>
                            <div className="relative">
                                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                                <input
                                    type="text"
                                    value={searchQuery}
                                    onChange={(e) => setSearchQuery(e.target.value)}
                                    className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
