"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import Link from "next/link";
import {
    Plus,
    FileText,
    Clock,
    CheckCircle,
    XCircle,
    DollarSign,
    Loader2
} from "lucide-react";
import { getUserLoanApplications } from "@/app/actions/loan-actions";
import { type LoanApplication, LoanStatus } from "@/types/strict";

export default function MyLoansPage() {
    const [loans, setLoans] = useState<LoanApplication[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadLoans();
    }, []);

    async function loadLoans() {
        setLoading(true);
        const result = await getUserLoanApplications();
        if (result.success) {
            setLoans(result.loans);
        }
        setLoading(false);
    }

    const getStatusColor = (status: LoanStatus) => {
        const colors: Record<string, string> = {
            [LoanStatus.PENDING]: 'bg-yellow-100 text-yellow-800',
            [LoanStatus.REVIEWING]: 'bg-orange-100 text-orange-800',
            [LoanStatus.APPROVED]: 'bg-green-100 text-green-800',
            [LoanStatus.REJECTED]: 'bg-red-100 text-red-800',
            [LoanStatus.DISBURSED]: 'bg-blue-100 text-blue-800',
            [LoanStatus.REPAID]: 'bg-purple-100 text-purple-800',
            [LoanStatus.DEFAULTED]: 'bg-slate-100 text-slate-800',
        };
        return colors[status] || 'bg-slate-100 text-slate-800';
    };

    const getStatusIcon = (status: LoanStatus) => {
        if (status === LoanStatus.PENDING || status === LoanStatus.REVIEWING) return <Clock className="w-4 h-4" />;
        if (status === LoanStatus.APPROVED || status === LoanStatus.DISBURSED || status === LoanStatus.REPAID)
            return <CheckCircle className="w-4 h-4" />;
        if (status === LoanStatus.REJECTED || status === LoanStatus.DEFAULTED)
            return <XCircle className="w-4 h-4" />;
        return null;
    };

    return (
        <div className="min-h-screen bg-linear-to-br from-slate-50 to-blue-50 p-8">
            <div className="max-w-6xl mx-auto">
                {/* Header */}
                <motion.div
                    initial={{ opacity: 0, y: -20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="mb-8 flex items-center justify-between"
                >
                    <div>
                        <h1 className="text-4xl font-bold text-slate-900 mb-2">
                            My Loan Applications
                        </h1>
                        <p className="text-slate-600">
                            Track and manage your loan applications
                        </p>
                    </div>

                    <Link
                        href="/loans/apply"
                        className="px-6 py-3 bg-[#1358ec] text-white rounded-xl font-medium hover:bg-[#1046c7] transition-colors flex items-center gap-2"
                    >
                        <Plus className="w-5 h-5" />
                        Apply for Loan
                    </Link>
                </motion.div>

                {/* Loading State */}
                {loading && (
                    <div className="flex items-center justify-center py-12">
                        <Loader2 className="w-8 h-8 animate-spin text-[#1358ec]" />
                    </div>
                )}

                {/* Empty State */}
                {!loading && loans.length === 0 && (
                    <motion.div
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        className="bg-white rounded-2xl p-12 text-center"
                    >
                        <FileText className="w-16 h-16 text-slate-300 mx-auto mb-4" />
                        <h3 className="text-xl font-bold text-slate-900 mb-2">
                            No Loan Applications Yet
                        </h3>
                        <p className="text-slate-600 mb-6">
                            Get started by applying for your first loan
                        </p>
                        <Link
                            href="/loans/apply"
                            className="inline-flex items-center gap-2 px-6 py-3 bg-[#1358ec] text-white rounded-xl font-medium hover:bg-[#1046c7] transition-colors"
                        >
                            <Plus className="w-5 h-5" />
                            Apply for Loan
                        </Link>
                    </motion.div>
                )}

                {/* Loans List */}
                {!loading && loans.length > 0 && (
                    <div className="space-y-6">
                        {loans.map((loan, index) => (
                            <motion.div
                                key={loan.id}
                                initial={{ opacity: 0, y: 20 }}
                                animate={{ opacity: 1, y: 0 }}
                                transition={{ delay: index * 0.1 }}
                                className="bg-white rounded-xl p-6 shadow-lg hover:shadow-xl transition-shadow"
                            >
                                <div className="flex items-start justify-between mb-4">
                                    <div className="flex-1">
                                        <div className="flex items-center gap-3 mb-2">
                                            <h3 className="text-2xl font-bold text-slate-900">
                                                ₦{loan.amount.toLocaleString()}
                                            </h3>
                                            <span className={`inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold ${getStatusColor(loan.status)}`}>
                                                {getStatusIcon(loan.status)}
                                                {loan.status.replace('_', ' ').toUpperCase()}
                                            </span>
                                        </div>
                                        <p className="text-sm text-slate-600">
                                            {loan.purpose.replace('_', ' ')} • {loan.repaymentPeriod} months
                                        </p>
                                    </div>

                                    <div className="text-right">
                                        <p className="text-xs text-slate-500">Applied</p>
                                        <p className="text-sm font-semibold text-slate-900">
                                            {new Date(loan.createdAt).toLocaleDateString()}
                                        </p>
                                    </div>
                                </div>

                                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-slate-50 rounded-xl">
                                    <div>
                                        <p className="text-xs text-slate-500 mb-1">Collateral</p>
                                        <p className="font-semibold text-slate-900 text-sm">{loan.collateral?.type || 'N/A'}</p>
                                    </div>
                                    <div>
                                        <p className="text-xs text-slate-500 mb-1">Value</p>
                                        <p className="font-semibold text-slate-900 text-sm">
                                            ₦{loan.collateral?.value?.toLocaleString() || '0'}
                                        </p>
                                    </div>
                                    <div>
                                        <p className="text-xs text-slate-500 mb-1">Business</p>
                                        <p className="font-semibold text-slate-900 text-sm">{loan.businessDetails?.name || 'N/A'}</p>
                                    </div>
                                    <div>
                                        <p className="text-xs text-slate-500 mb-1">Application ID</p>
                                        <p className="font-mono text-xs text-slate-900">
                                            {loan.id.slice(0, 12)}...
                                        </p>
                                    </div>
                                </div>

                                {/* Rejection Reason */}
                                {loan.status === LoanStatus.REJECTED && loan.rejectedReason && (
                                    <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-xl">
                                        <p className="text-sm font-semibold text-red-900 mb-1">
                                            Rejection Reason:
                                        </p>
                                        <p className="text-sm text-red-700">{loan.rejectedReason}</p>
                                    </div>
                                )}

                                {/* Approval Notes */}
                                {(loan.status === LoanStatus.APPROVED || loan.status === LoanStatus.DISBURSED) && (
                                    <div className="mt-4 p-4 bg-green-50 border border-green-200 rounded-xl">
                                        <p className="text-sm font-semibold text-green-900">
                                            ✓ Approved {loan.approvedAt && `on ${new Date(loan.approvedAt).toLocaleDateString()}`}
                                        </p>
                                        {loan.status === LoanStatus.DISBURSED && (
                                            <p className="text-sm text-green-700 mt-1">
                                                Funds have been disbursed to your account
                                            </p>
                                        )}
                                    </div>
                                )}
                            </motion.div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { useSession } from "next-auth/react";
import Image from "next/image";
import { ShoppingCart, CreditCard, ArrowLeft, Loader2, CheckCircle, X, Store } from "lucide-react";
import { formatCurrency } from "@/lib/utils";
import { initializeOrderPaymentAction, type CartItem } from "@/app/actions/marketplace-payment";
import { useToast } from "@/contexts/ToastContext";
import PhoneInput, { isValidNigerianPhone } from "@/components/ui/PhoneInput";
import type { Product } from "@/lib/types/marketplace";

// Disable static generation for this page - must be client-only due to Paystack
export const dynamic = 'force-dynamic';

interface LocalCartItem extends Product {
    quantity: number;
}

export default function CheckoutPage() {
    const router = useRouter();
    const { data: session } = useSession();
    const { showToast } = useToast();
    const [cart, setCart] = useState<LocalCartItem[]>([]);
    const [isProcessing, setIsProcessing] = useState(false);
    const [paymentMethod, setPaymentMethod] = useState<"paystack">("paystack");
    const [email, setEmail] = useState("");
    const [phone, setPhone] = useState("");
    const [phoneError, setPhoneError] = useState<string>("");
    const [deliveryAddress, setDeliveryAddress] = useState({
        street: "",
        city: "",
        state: "",
        lga: "",
    });
    const [isClient, setIsClient] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        setIsClient(true);
        if (session?.user?.email) setEmail(session.user.email);

        // Use user-scoped cart key to match what product page sets
        const userId = session?.user?.id;
        const cartKey = userId ? `marketplace_cart_${userId}` : "marketplace_cart";
        const savedCart = localStorage.getItem(cartKey);
        if (savedCart) {
            setCart(JSON.parse(savedCart));
        } else {
            router.push("/marketplace");
        }
    }, [router, session]);

    const subtotal = cart.reduce((sum, item) => sum + (item.pricingTiers[0]?.price || 0) * item.quantity, 0);
    const deliveryFee = 5000;

    async function handlePaystackCheckout() {
        if (!session) {
            router.push("/auth/login?redirect=/marketplace/checkout");
            return;
        }

        if (!email || !phone) {
            setError("Please provide your email and phone number");
            return;
        }

        // Validate phone number
        if (!isValidNigerianPhone(phone)) {
            setPhoneError("Please enter a valid Nigerian phone number");
            return;
        }

        if (cart.length === 0) {
            setError("Your cart is empty");
            return;
        }

        setIsProcessing(true);
        setError(null);
        setPhoneError("");

        try {
            // Prepare cart items for payment
            const cartItems: CartItem[] = cart.map(item => ({
                id: item.id,
                title: item.title,
                sellerId: item.sellerId,
                price: item.pricingTiers[0]?.price || 0,
                quantity: item.quantity,
                unit: item.unit,
            }));

            // Initialize payment
            const result = await initializeOrderPaymentAction(
                cartItems,
                email,
                phone,
                deliveryFee
            );

            if (result.success && result.data) {
                // Redirect to Paystack for payment
                window.location.href = result.data.authorizationUrl;
            } else {
                setError(result.error || "Failed to initialize payment");
                setIsProcessing(false);
            }
        } catch (err) {
            setError("An error occurred while processing your payment");
            setIsProcessing(false);
        }
    };



    if (!isClient || cart.length === 0) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <div className="text-center">
                    <Loader2 className="w-12 h-12 animate-spin text-primary mx-auto mb-4" />
                    <p className="text-slate-600">Loading checkout...</p>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-50 py-8 px-4">
            <div className="max-w-6xl mx-auto">
                {/* Header */}
                <button
                    onClick={() => router.back()}
                    className="flex items-center gap-2 text-slate-600 hover:text-slate-900 mb-6 transition"
                >
                    <ArrowLeft className="w-5 h-5" />
                    Back to Marketplace
                </button>

                <h1 className="text-3xl font-bold text-slate-900 mb-8">
                    Checkout
                </h1>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Order Summary */}
                    <div className="lg:col-span-2 space-y-6">
                        {/* Cart Items */}
                        <div className="bg-white rounded-2xl p-6">
                            <h2 className="text-xl font-bold text-slate-900 mb-4">
                                Order Summary
                            </h2>
                            <div className="space-y-4">
                                {cart.map((item) => {
                                    const price = item.pricingTiers[0]?.price || 0;
                                    return (
                                        <div
                                            key={item.id}
                                            className="flex items-start gap-4 pb-4 border-b border-slate-200 last:border-0"
                                        >
                                            <div className="relative w-20 h-20 rounded-lg overflow-hidden bg-slate-100">
                                                {item.images[0] ? (
                                                    <Image
                                                        src={item.images[0]}
                                                        alt={item.title}
                                                        fill
                                                        className="object-cover"
                                                    />
                                                ) : (
                                                    <Store className="w-8 h-8 text-gray-400 mx-auto mt-6" />
                                                )}
                                            </div>
                                            <div className="flex-1">
                                                <h3 className="font-bold text-slate-900">
                                                    {item.title}
                                                </h3>
                                                <p className="text-sm text-slate-600">
                                                    {formatCurrency(price)} × {item.quantity} {item.unit}
                                                </p>
                                            </div>
                                            <p className="font-bold text-primary">
                                                {formatCurrency(price * item.quantity)}
                                            </p>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>

                        {/* Contact Information */}
                        <div className="bg-white rounded-2xl p-6">
                            <h2 className="text-xl font-bold text-slate-900 mb-4">
                                Contact Information
                            </h2>
                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Email Address
                                    </label>
                                    <input
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        placeholder="your.email@example.com"
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-primary"
                                        required
                                    />
                                </div>
                                <PhoneInput
                                    label="Phone Number"
                                    value={phone}
                                    onChange={(e) => setPhone(e.target.value)}
                                    error={phoneError}
                                    required
                                />
                            </div>
                        </div>


                    </div>

                    {/* Order Total */}
                    <div className="lg:col-span-1">
                        <div className="bg-white rounded-2xl p-6 sticky top-8">
                            <h2 className="text-xl font-bold text-slate-900 mb-4">
                                Order Total
                            </h2>
                            <div className="space-y-3 mb-6">
                                <div className="flex justify-between text-slate-600">
                                    <span>Subtotal</span>
                                    <span>{formatCurrency(subtotal)}</span>
                                </div>
                                <div className="flex justify-between text-slate-600">
                                    <span>Delivery Fee</span>
                                    <span>{formatCurrency(deliveryFee)}</span>
                                </div>
                                <div className="pt-3 border-t border-slate-200 flex justify-between text-lg font-bold">
                                    <span className="text-slate-900">Total</span>
                                    <span className="text-primary">{formatCurrency(subtotal + deliveryFee)}</span>
                                </div>
                            </div>


                            <div className="mb-6">
                                <label className="block text-sm font-semibold text-slate-900 mb-3">
                                    Payment Method
                                </label>
                                <div className="p-4 border-2 border-primary bg-primary/10 rounded-xl flex items-center gap-3">
                                    <CreditCard className="w-6 h-6 text-primary" />
                                    <div>
                                        <p className="font-semibold text-slate-900">Card Payment (Paystack)</p>
                                        <p className="text-xs text-slate-600">Pay securely with your debit or credit card</p>
                                    </div>
                                </div>
                            </div>

                            {/* Error Display */}
                            {error && (
                                <div className="bg-red-50 border border-red-200 rounded-xl p-4 mb-4">
                                    <p className="text-sm text-red-600">{error}</p>
                                </div>
                            )}

                            {process.env.NEXT_PUBLIC_PAYSTACK_PUBLIC_KEY ? (
                                <button
                                    onClick={handlePaystackCheckout}
                                    disabled={isProcessing || !email || !phone}
                                    className="w-full px-6 py-4 bg-primary text-white font-bold rounded-xl hover:bg-primary/90 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
                                >
                                    {isProcessing ? (
                                        <>
                                            <Loader2 className="w-5 h-5 animate-spin" />
                                            Processing...
                                        </>
                                    ) : (
                                        <>
                                            <CreditCard className="w-5 h-5" />
                                            Complete Payment
                                        </>
                                    )}
                                </button>
                            ) : (
                                <div className="p-4 bg-yellow-50 border border-yellow-200 rounded-xl">
                                    <p className="text-sm text-yellow-800 font-semibold mb-2">
                                        Payment Temporarily Unavailable
                                    </p>
                                    <p className="text-xs text-yellow-700">
                                        Please contact support to complete your order.
                                    </p>
                                    <button
                                        disabled
                                        className="w-full mt-3 px-6 py-3 bg-slate-300 text-slate-500 font-bold rounded-xl cursor-not-allowed"
                                    >
                                        Payment Disabled
                                    </button>
                                </div>
                            )}

                            <p className="text-xs text-center text-slate-500 mt-4">
                                All payments are escrow-protected for your security
                            </p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

