import { FileText, Image, Package } from "lucide-react";

interface BusinessVerificationData {
    businessRegistration?: { name: string; url: string };
    cacNumber?: string;
    companyName?: string;
    taxId?: string;
    farmPhotos?: { name: string; url: string }[];
    productSamples?: { name: string; url: string }[];
}

interface BusinessVerificationStepProps {
    data?: BusinessVerificationData;
    onChange: (data: BusinessVerificationData) => void;
    onNext: () => void;
    onBack: () => void;
}

export default function BusinessVerificationStep({ data = {}, onChange, onNext, onBack }: BusinessVerificationStepProps) {
    const [documents, setDocuments] = useState<BusinessVerificationData>(data);

    const updateDocuments = (updates: Partial<BusinessVerificationData>) => {
        setDocuments(prev => {
            const next = { ...prev, ...updates };
            onChange(next);
            return next;
        });
    };

    return (
        <div className="space-y-8">
            {/* Header */}
            <div className="text-center">
                <h2 className="text-3xl font-bold text-slate-900 mb-3">
                    Business Verification
                </h2>
                <p className="text-lg text-slate-600">
                    Upload documents to verify your business
                </p>
            </div>

            <div className="max-w-3xl mx-auto space-y-6">
                {/* Info Banner */}
                <div className="bg-blue-50 border border-blue-200 rounded-xl p-4">
                    <div className="flex items-start gap-3">
                        <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center shrink-0 mt-0.5">
                            <span className="text-blue-600 text-sm font-bold">ℹ</span>
                        </div>
                        <div className="text-sm">
                            <p className="font-semibold text-blue-900 mb-1">
                                Document Requirements
                            </p>
                            <p className="text-blue-800">
                                All documents must be clear and legible. Supported formats: PDF, JPG, PNG (max 5MB each).
                                Verification typically takes 1-3 business days.
                            </p>
                        </div>
                    </div>
                </div>

                {/* Business Registration Certificate */}
                <div>
                    <div className="flex items-center gap-2 mb-3">
                        <FileText className="w-5 h-5 text-slate-600" />
                        <label className="block text-sm font-semibold text-slate-900">
                            Business Registration Certificate (Optional)
                        </label>
                    </div>
                    <p className="text-sm text-slate-600 mb-3">
                        CAC certificate for registered businesses or cooperative registration documents
                    </p>
                    <DocumentUpload
                        label=""
                        accept=".pdf,.jpg,.jpeg,.png"
                        maxSize={5}
                        onUpload={(file) => updateDocuments({ businessRegistration: { name: file.name, url: URL.createObjectURL(file) } })}
                    />

                    {documents.businessRegistration && (
                        <div className="mt-4 p-4 border border-slate-200 rounded-xl bg-white space-y-4">
                            <h4 className="font-semibold text-slate-900 text-sm">Business Registration Details</h4>
                            <p className="text-xs text-slate-500">
                                Our team will manually review your registration document within 1-3 business days.
                            </p>
                            <div className="grid grid-cols-1 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1">
                                        Company Name
                                    </label>
                                    <input
                                        type="text"
                                        value={documents.companyName || ""}
                                        onChange={(e) => updateDocuments({ companyName: e.target.value })}
                                        placeholder="Enter full company name"
                                        className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 text-sm"
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-700 mb-1">
                                        RC Number / Business Number
                                    </label>
                                    <input
                                        type="text"
                                        value={documents.cacNumber || ""}
                                        onChange={(e) => updateDocuments({ cacNumber: e.target.value })}
                                        placeholder="RC-123456"
                                        className="w-full px-3 py-2 bg-slate-50 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 text-sm"
                                    />
                                </div>
                            </div>
                        </div>
                    )}
                </div>

                {/* Tax ID — plain text, admin reviews manually */}
                <div>
                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                        Tax Identification Number (TIN){" "}
                        <span className="text-slate-400 text-xs font-normal">(Optional)</span>
                    </label>
                    <input
                        type="text"
                        value={documents.taxId || ""}
                        onChange={(e) => updateDocuments({ taxId: e.target.value })}
                        placeholder="Enter your TIN"
                        className="w-full px-4 py-3 border border-slate-300 rounded-xl bg-white text-slate-900 focus:ring-2 focus:ring-green-500 focus:border-transparent"
                    />
                    <p className="mt-2 text-sm text-slate-600">
                        Collected for tax compliance — reviewed by our team
                    </p>
                </div>

                {/* Farm/Business Location Photos */}
                <div>
                    <div className="flex items-center gap-2 mb-3">
                        <Image className="w-5 h-5 text-slate-600" />
                        <label className="block text-sm font-semibold text-slate-900">
                            Farm/Business Location Photos (Optional)
                        </label>
                    </div>
                    <p className="text-sm text-slate-600 mb-3">
                        Upload 2-4 photos showing your farm or business facility
                    </p>
                    <div className="grid grid-cols-2 gap-4">
                        <DocumentUpload
                            label="Photo 1"
                            accept=".jpg,.jpeg,.png"
                            maxSize={5}
                            onUpload={(file) => {
                                const photos = documents.farmPhotos ? [...documents.farmPhotos] : [];
                                photos[0] = { name: file.name, url: URL.createObjectURL(file) };
                                updateDocuments({ farmPhotos: photos });
                            }}
                        />
                        <DocumentUpload
                            label="Photo 2"
                            accept=".jpg,.jpeg,.png"
                            maxSize={5}
                            onUpload={(file) => {
                                const photos = documents.farmPhotos ? [...documents.farmPhotos] : [];
                                photos[1] = { name: file.name, url: URL.createObjectURL(file) };
                                updateDocuments({ farmPhotos: photos });
                            }}
                        />
                    </div>
                </div>

                {/* Product Sample Photos */}
                <div>
                    <div className="flex items-center gap-2 mb-3">
                        <Package className="w-5 h-5 text-slate-600" />
                        <label className="block text-sm font-semibold text-slate-900">
                            Product Sample Photos (Optional)
                        </label>
                    </div>
                    <p className="text-sm text-slate-600 mb-3">
                        Upload photos of your products to showcase quality
                    </p>
                    <div className="grid grid-cols-2 gap-4">
                        <DocumentUpload
                            label="Product 1"
                            accept=".jpg,.jpeg,.png"
                            maxSize={5}
                            onUpload={(file) => {
                                const samples = documents.productSamples ? [...documents.productSamples] : [];
                                samples[0] = { name: file.name, url: URL.createObjectURL(file) };
                                updateDocuments({ productSamples: samples });
                            }}
                        />
                        <DocumentUpload
                            label="Product 2"
                            accept=".jpg,.jpeg,.png"
                            maxSize={5}
                            onUpload={(file) => {
                                const samples = documents.productSamples ? [...documents.productSamples] : [];
                                samples[1] = { name: file.name, url: URL.createObjectURL(file) };
                                updateDocuments({ productSamples: samples });
                            }}
                        />
                    </div>
                </div>

                {/* Verification Timeline */}
                <div className="bg-slate-50 border border-slate-200 rounded-xl p-6">
                    <h4 className="font-bold text-slate-900 mb-3">
                        What happens next?
                    </h4>
                    <ol className="space-y-2 text-sm text-slate-900">
                        <li className="flex items-start gap-3">
                            <span className="font-bold text-green-600">1.</span>
                            <span>Our team reviews your documents within 24 hours</span>
                        </li>
                        <li className="flex items-start gap-3">
                            <span className="font-bold text-green-600">2.</span>
                            <span>We may contact you for additional information</span>
                        </li>
                        <li className="flex items-start gap-3">
                            <span className="font-bold text-green-600">3.</span>
                            <span>You'll receive an email notification about your verification status</span>
                        </li>
                        <li className="flex items-start gap-3">
                            <span className="font-bold text-green-600">4.</span>
                            <span>Once approved, you can start listing products immediately</span>
                        </li>
                    </ol>
                </div>
            </div>

            {/* Navigation */}
            <div className="flex justify-between pt-6">
                <button
                    onClick={onBack}
                    className="px-8 py-3 border-2 border-slate-300 text-slate-900 font-semibold rounded-xl hover:bg-slate-50 transition-colors"
                >
                    Back
                </button>
                <button
                    onClick={onNext}
                    className="px-8 py-3 bg-green-600 text-white font-semibold rounded-xl hover:bg-green-700 transition-colors"
                >
                    Continue
                </button>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import {
    Package, DollarSign, Award, Video,
    ArrowLeft, Plus, X, Upload
} from "lucide-react";
import Link from "next/link";
import { useToast } from "@/contexts/ToastContext";
import LoadingButton from "@/components/ui/LoadingButton";

export default function AddProductPage() {
    const router = useRouter();
    const [isSubmitting, setIsSubmitting] = useState(false);

    const [formData, setFormData] = useState({
        name: "",
        category: "",
        description: "",
        specifications: "",
        unit: "kg",
        minOrder: 1,
        stockQuantity: 0,
        retailPrice: 0,
        bulkPrice: 0,
        exportPrice: 0,
        certifications: [] as string[],
        escrowAvailable: true,
    });

    const [media, setMedia] = useState({
        images: [] as File[],
        video: null as File | null,
    });

    const [newCertification, setNewCertification] = useState("");

    const categories = [
        "Grains & Cereals",
        "Tubers & Roots",
        "Fruits",
        "Vegetables",
        "Spices",
        "Nuts & Seeds",
        "Processed Foods",
        "Livestock Products",
        "Poultry Products",
        "Other"
    ];

    const commonCertifications = [
        "Organic Certified",
        "NAFDAC Approved",
        "Halal Certified",
        "Fair Trade",
        "ISO 22000",
        "HACCP Certified",
        "Non-GMO",
        "Rainforest Alliance"
    ];

    const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const files = Array.from(e.target.files || []);
        setMedia(prev => ({ ...prev, images: [...prev.images, ...files].slice(0, 5) }));
    };

    const handleVideoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0] || null;
        setMedia(prev => ({ ...prev, video: file }));
    };

    const removeImage = (index: number) => {
        setMedia(prev => ({
            ...prev,
            images: prev.images.filter((_, i) => i !== index)
        }));
    };

    const addCertification = (cert: string) => {
        if (cert && !formData.certifications.includes(cert)) {
            setFormData(prev => ({
                ...prev,
                certifications: [...prev.certifications, cert]
            }));
        }
        setNewCertification("");
    };

    const removeCertification = (cert: string) => {
        setFormData(prev => ({
            ...prev,
            certifications: prev.certifications.filter(c => c !== cert)
        }));
    };

    const { showToast } = useToast();

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsSubmitting(true);

        try {
            const submitData = new FormData();

            // Add form fields
            Object.entries(formData).forEach(([key, value]) => {
                if (key === "certifications") {
                    submitData.append(key, JSON.stringify(value));
                } else {
                    submitData.append(key, String(value));
                }
            });

            // Add images
            media.images.forEach((image, index) => {
                submitData.append(`image${index}`, image);
            });

            // Add video
            if (media.video) {
                submitData.append("video", media.video);
            }

            const response = await fetch("/api/marketplace/create-product", {
                method: "POST",
                body: submitData,
            });

            const data = await response.json();

            if (data.success) {
                showToast("Product listed successfully!", "success");
                setTimeout(() => router.push("/marketplace/sell"), 1000);
            } else {
                showToast(data.message || "Failed to create product", "error");
            }
        } catch (error) {
            showToast("An error occurred while creating the product", "error");
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="min-h-screen bg-slate-50 py-8">
            <div className="max-w-5xl mx-auto px-4">
                <Link
                    href="/marketplace/sell"
                    className="inline-flex items-center gap-2 text-primary hover:underline mb-6"
                >
                    <ArrowLeft className="w-4 h-4" />
                    Back to Seller Dashboard
                </Link>

                <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
                    {/* Header */}
                    <div className="bg-linear-to-r from-green-600 to-emerald-600 p-8 text-white">
                        <h1 className="text-3xl font-bold mb-2">Add New Product</h1>
                        <p className="text-green-100">
                            Create a listing for your agricultural product
                        </p>
                    </div>

                    <form onSubmit={handleSubmit} className="p-8 space-y-8">
                        {/* Basic Information */}
                        <section>
                            <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                                <Package className="w-6 h-6" />
                                Basic Information
                            </h2>

                            <div className="space-y-6">
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                    <div>
                                        <label className="block text-sm font-semibold text-slate-900 mb-2">
                                            Product Name *
                                        </label>
                                        <input
                                            type="text"
                                            value={formData.name}
                                            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                            placeholder="e.g., Premium Yam Tubers"
                                            required
                                        />
                                    </div>

                                    <div>
                                        <label className="block text-sm font-semibold text-slate-900 mb-2">
                                            Category *
                                        </label>
                                        <select
                                            value={formData.category}
                                            onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                                            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                            required
                                        >
                                            <option value="">Select Category</option>
                                            {categories.map(cat => (
                                                <option key={cat} value={cat}>{cat}</option>
                                            ))}
                                        </select>
                                    </div>
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Description *
                                    </label>
                                    <textarea
                                        value={formData.description}
                                        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                        rows={4}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        placeholder="Provide a detailed description of your product..."
                                        required
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Specifications
                                    </label>
                                    <textarea
                                        value={formData.specifications}
                                        onChange={(e) => setFormData({ ...formData, specifications: e.target.value })}
                                        rows={3}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        placeholder="Add any specifications (size, color, variety, origin, etc.)"
                                    />
                                </div>
                            </div>
                        </section>

                        {/* Pricing Tiers */}
                        <section>
                            <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                                <DollarSign className="w-6 h-6" />
                                Pricing Tiers
                            </h2>

                            <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 mb-6">
                                <p className="text-sm text-blue-900">
                                    💡 Set different prices for retail, bulk, and export orders. Bulk pricing applies to orders above MOQ.
                                </p>
                            </div>

                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Retail Price (₦ per {formData.unit}) *
                                    </label>
                                    <input
                                        type="number"
                                        value={formData.retailPrice}
                                        onChange={(e) => setFormData({ ...formData, retailPrice: Number(e.target.value) })}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        placeholder="0"
                                        min="0"
                                        step="100"
                                        required
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Bulk Price (₦ per {formData.unit})
                                    </label>
                                    <input
                                        type="number"
                                        value={formData.bulkPrice}
                                        onChange={(e) => setFormData({ ...formData, bulkPrice: Number(e.target.value) })}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        placeholder="Optional"
                                        min="0"
                                        step="100"
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Export Price (₦ per {formData.unit})
                                    </label>
                                    <input
                                        type="number"
                                        value={formData.exportPrice}
                                        onChange={(e) => setFormData({ ...formData, exportPrice: Number(e.target.value) })}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        placeholder="Optional"
                                        min="0"
                                        step="100"
                                    />
                                </div>
                            </div>
                        </section>

                        {/* Inventory & MOQ */}
                        <section>
                            <h2 className="text-2xl font-bold text-slate-900 mb-6">
                                Inventory & Minimum Order
                            </h2>

                            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Unit *
                                    </label>
                                    <select
                                        value={formData.unit}
                                        onChange={(e) => setFormData({ ...formData, unit: e.target.value })}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        required
                                    >
                                        <option value="kg">Kilogram (kg)</option>
                                        <option value="ton">Ton</option>
                                        <option value="bag">Bag</option>
                                        <option value="carton">Carton</option>
                                        <option value="piece">Piece</option>
                                        <option value="liter">Liter</option>
                                    </select>
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Minimum Order Quantity (MOQ) *
                                    </label>
                                    <input
                                        type="number"
                                        value={formData.minOrder}
                                        onChange={(e) => setFormData({ ...formData, minOrder: Number(e.target.value) })}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        placeholder="1"
                                        min="1"
                                        required
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Available Stock *
                                    </label>
                                    <input
                                        type="number"
                                        value={formData.stockQuantity}
                                        onChange={(e) => setFormData({ ...formData, stockQuantity: Number(e.target.value) })}
                                        className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        placeholder="0"
                                        min="0"
                                        required
                                    />
                                </div>
                            </div>
                        </section>

                        {/* Certifications */}
                        <section>
                            <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                                <Award className="w-6 h-6" />
                                Certifications
                            </h2>

                            <div className="space-y-4">
                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Add Certification
                                    </label>
                                    <div className="flex gap-2">
                                        <select
                                            value={newCertification}
                                            onChange={(e) => setNewCertification(e.target.value)}
                                            className="flex-1 px-4 py-3 bg-slate-50 border border-slate-200 rounded-lg text-slate-900 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        >
                                            <option value="">Select or enter custom certification</option>
                                            {commonCertifications.map(cert => (
                                                <option key={cert} value={cert}>{cert}</option>
                                            ))}
                                        </select>
                                        <button
                                            type="button"
                                            onClick={() => addCertification(newCertification)}
                                            className="px-6 py-3 bg-green-600 hover:bg-green-700 text-white font-bold rounded-lg transition-all"
                                        >
                                            <Plus className="w-5 h-5" />
                                        </button>
                                    </div>
                                </div>

                                {formData.certifications.length > 0 && (
                                    <div className="flex flex-wrap gap-2">
                                        {formData.certifications.map((cert, index) => (
                                            <div
                                                key={index}
                                                className="flex items-center gap-2 px-4 py-2 bg-green-100 text-green-700 rounded-lg"
                                            >
                                                <Award className="w-4 h-4" />
                                                <span className="font-semibold">{cert}</span>
                                                <button
                                                    type="button"
                                                    onClick={() => removeCertification(cert)}
                                                    className="p-1 hover:bg-green-200 rounded transition-colors"
                                                >
                                                    <X className="w-4 h-4" />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        </section>

                        {/* Media Upload */}
                        <section>
                            <h2 className="text-2xl font-bold text-slate-900 mb-6 flex items-center gap-2">
                                <Video className="w-6 h-6" />
                                Product Media
                            </h2>

                            <div className="space-y-6">
                                {/* Images */}
                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Product Images (Max 5) *
                                    </label>
                                    <div className="border-2 border-dashed border-slate-300 rounded-lg p-6">
                                        {media.images.length > 0 ? (
                                            <div className="grid grid-cols-3 gap-4 mb-4">
                                                {media.images.map((img, index) => (
                                                    <div key={index} className="relative">
                                                        <img
                                                            src={URL.createObjectURL(img)}
                                                            alt={`Product ${index + 1}`}
                                                            className="w-full h-32 object-cover rounded-lg"
                                                        />
                                                        <button
                                                            type="button"
                                                            onClick={() => removeImage(index)}
                                                            className="absolute top-2 right-2 p-1 bg-red-600 hover:bg-red-700 text-white rounded-full"
                                                        >
                                                            <X className="w-4 h-4" />
                                                        </button>
                                                    </div>
                                                ))}
                                            </div>
                                        ) : null}

                                        {media.images.length < 5 && (
                                            <label className="flex flex-col items-center cursor-pointer">
                                                <Upload className="w-12 h-12 text-slate-400 mb-3" />
                                                <p className="text-sm font-semibold text-slate-900 mb-1">
                                                    Click to upload images
                                                </p>
                                                <p className="text-xs text-slate-500">JPG, PNG (max 5MB each)</p>
                                                <input
                                                    type="file"
                                                    accept="image/*"
                                                    multiple
                                                    onChange={handleImageSelect}
                                                    className="hidden"
                                                />
                                            </label>
                                        )}
                                    </div>
                                </div>

                                {/* Video */}
                                <div>
                                    <label className="block text-sm font-semibold text-slate-900 mb-2">
                                        Product Video (Optional)
                                    </label>
                                    <div className="border-2 border-dashed border-slate-300 rounded-lg p-6">
                                        {media.video ? (
                                            <div className="flex items-center justify-between">
                                                <div className="flex items-center gap-3">
                                                    <Video className="w-8 h-8 text-green-600" />
                                                    <div>
                                                        <p className="font-semibold text-slate-900">{media.video.name}</p>
                                                        <p className="text-sm text-slate-500">{(media.video.size / 1024 / 1024).toFixed(2)} MB</p>
                                                    </div>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={() => setMedia(prev => ({ ...prev, video: null }))}
                                                    className="p-2 hover:bg-red-100 rounded-lg transition-colors"
                                                >
                                                    <X className="w-5 h-5 text-red-600" />
                                                </button>
                                            </div>
                                        ) : (
                                            <label className="flex flex-col items-center cursor-pointer">
                                                <Video className="w-12 h-12 text-slate-400 mb-3" />
                                                <p className="text-sm font-semibold text-slate-900 mb-1">
                                                    Click to upload video
                                                </p>
                                                <p className="text-xs text-slate-500">MP4, MOV (max 50MB)</p>
                                                <input
                                                    type="file"
                                                    accept="video/*"
                                                    onChange={handleVideoSelect}
                                                    className="hidden"
                                                />
                                            </label>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </section>

                        {/* Options */}
                        <section>
                            <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-lg">
                                <input
                                    type="checkbox"
                                    id="escrow"
                                    checked={formData.escrowAvailable}
                                    onChange={(e) => setFormData({ ...formData, escrowAvailable: e.target.checked })}
                                    className="w-5 h-5 text-green-600 rounded focus:ring-2 focus:ring-green-500"
                                />
                                <label htmlFor="escrow" className="text-sm font-semibold text-slate-900">
                                    Enable Escrow Protection (Recommended for buyer trust)
                                </label>
                            </div>
                        </section>

                        {/* Submit Button */}
                        <div className="flex gap-4 pt-4">
                            <LoadingButton
                                type="submit"
                                disabled={media.images.length === 0}
                                loading={isSubmitting}
                                loadingText="Creating Product..."
                                variant="success"
                                size="lg"
                                className="flex-1"
                            >
                                List Product
                            </LoadingButton>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import { useRouter } from "next/navigation";
import {
    Package, TrendingUp, ShoppingCart, DollarSign, Eye, Star,
    Plus, Edit, Trash2, BarChart3, Loader2, AlertCircle
} from "lucide-react";
import { getSellerProductsAction, getSellerVerificationAction, deleteProductAction } from "@/app/actions/marketplace";
import type { Product } from "@/lib/types/marketplace";
import { useToast } from "@/contexts/ToastContext";

export default function SellerDashboardPage() {
    const { data: session, status } = useSession();
    const router = useRouter();

    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [verification, setVerification] = useState<any>(null);
    const [filterStatus, setFilterStatus] = useState<"all" | "active" | "suspended" | "sold_out">("all");
    const { showToast } = useToast();

    async function handleDeleteProduct(productId: string, productTitle: string) {
        if (!confirm(`Delete "${productTitle}"? This action cannot be undone.`)) {
            return;
        }

        try {
            const result = await deleteProductAction(productId);
            if (result.success) {
                showToast(result.message || "Product deleted successfully", "success");
                loadSellerData();
            } else {
                showToast(result.error || "Failed to delete product", "error");
            }
        } catch (error) {
            showToast("An error occurred while deleting product", "error");
        }
    }

    useEffect(() => {
        if (status === "unauthenticated") {
            router.push("/auth/login");
        } else if (status === "authenticated") {
            loadSellerData();
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [status]);

    async function loadSellerData() {
        setLoading(true);
        const [productsRes, verificationRes] = await Promise.all([
            getSellerProductsAction(),
            getSellerVerificationAction()
        ]);

        if (productsRes.success) {
            setProducts(productsRes.products || []);
        }

        if (verificationRes.success) {
            setVerification(verificationRes.verification);
        }

        setLoading(false);
    };

    const filteredProducts = products.filter(p => {
        if (filterStatus === "all") return true;
        if (filterStatus === "sold_out") return p.availableQuantity === 0;
        if (filterStatus === "suspended") return p.status === "suspended";
        return p.status === filterStatus;
    });

    // Calculate stats
    const stats = {
        totalProducts: products.length,
        activeProducts: products.filter(p => p.status === "active").length,
        totalOrders: products.reduce((sum, p) => sum + (p.orders || 0), 0),
        totalViews: products.reduce((sum, p) => sum + (p.views || 0), 0),
        averageRating: products.length > 0
            ? products.reduce((sum, p) => sum + (p.rating || 0), 0) / products.length
            : 0,
        revenue: 0, // Would calculate from orders
    };

    if (loading || status === "loading") {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <Loader2 className="w-12 h-12 animate-spin text-blue-600" />
            </div>
        );
    }

    // Show verification required message
    if (!verification || verification.status !== "approved") {
        return (
            <div className="min-h-screen bg-slate-50 p-8">
                <div className="max-w-4xl mx-auto">
                    <div className="bg-white rounded-2xl p-8 text-center">
                        <AlertCircle className="w-16 h-16 text-yellow-600 mx-auto mb-4" />
                        <h1 className="text-2xl font-bold text-slate-900 mb-2">
                            Seller Verification Required
                        </h1>
                        <p className="text-slate-600 mb-6">
                            {!verification
                                ? "You need to complete seller verification before listing products."
                                : verification.status === "pending"
                                    ? "Your seller verification is pending review."
                                    : "Your seller verification was not approved. Please contact support."}
                        </p>
                        <button
                            onClick={() => router.push(verification ? "/marketplace" : "/marketplace/seller-verification")}
                            className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-xl transition"
                        >
                            {verification ? "Back to Marketplace" : "Start Verification"}
                        </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-50 py-8 px-4">
            <div className="max-w-7xl mx-auto">
                {/* Header */}
                <div className="flex items-center justify-between mb-8">
                    <div>
                        <h1 className="text-3xl font-bold text-slate-900 mb-2">
                            Seller Dashboard
                        </h1>
                        <p className="text-slate-600">
                            Manage your products and track performance
                        </p>
                    </div>
                    <button
                        onClick={() => router.push("/marketplace/sell/create")}
                        className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-xl transition flex items-center gap-2"
                    >
                        <Plus className="w-5 h-5" />
                        <span>New Product</span>
                    </button>
                </div>

                {/* Stats Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                    <div className="bg-white rounded-xl p-6 elevation-2">
                        <div className="flex items-center justify-between mb-4">
                            <Package className="w-8 h-8 text-blue-600" />
                            <span className="text-3xl font-bold text-slate-900">
                                {stats.totalProducts}
                            </span>
                        </div>
                        <p className="text-sm font-medium text-slate-600">Total Products</p>
                        <p className="text-xs text-green-600 mt-1">{stats.activeProducts} active</p>
                    </div>

                    <div className="bg-white rounded-xl p-6 elevation-2">
                        <div className="flex items-center justify-between mb-4">
                            <ShoppingCart className="w-8 h-8 text-green-600" />
                            <span className="text-3xl font-bold text-slate-900">
                                {stats.totalOrders}
                            </span>
                        </div>
                        <p className="text-sm font-medium text-slate-600">Total Orders</p>
                        <p className="text-xs text-blue-600 mt-1">All time</p>
                    </div>

                    <div className="bg-white rounded-xl p-6 elevation-2">
                        <div className="flex items-center justify-between mb-4">
                            <Eye className="w-8 h-8 text-purple-600" />
                            <span className="text-3xl font-bold text-slate-900">
                                {stats.totalViews}
                            </span>
                        </div>
                        <p className="text-sm font-medium text-slate-600">Total Views</p>
                        <p className="text-xs text-slate-500 mt-1">Product impressions</p>
                    </div>

                    <div className="bg-white rounded-xl p-6 elevation-2">
                        <div className="flex items-center justify-between mb-4">
                            <Star className="w-8 h-8 text-yellow-600" />
                            <span className="text-3xl font-bold text-slate-900">
                                {stats.averageRating.toFixed(1)}
                            </span>
                        </div>
                        <p className="text-sm font-medium text-slate-600">Avg Rating</p>
                        <p className="text-xs text-slate-500 mt-1">Across all products</p>
                    </div>
                </div>

                {/* Filter Tabs */}
                <div className="bg-white rounded-xl p-6 elevation-2 mb-6">
                    <div className="flex items-center gap-4 overflow-x-auto">
                        {[
                            { key: "all", label: "All Products", count: products.length },
                            { key: "active", label: "Active", count: stats.activeProducts },
                            { key: "suspended", label: "Suspended", count: products.filter(p => p.status === "suspended").length },
                            { key: "sold_out", label: "Sold Out", count: products.filter(p => p.availableQuantity === 0).length }
                        ].map((tab) => (
                            <button
                                key={tab.key}
                                onClick={() => setFilterStatus(tab.key as "all" | "active" | "suspended" | "sold_out")}
                                className={`px-4 py-2 rounded-lg font-medium transition whitespace-nowrap ${filterStatus === tab.key
                                    ? "bg-blue-600 text-white"
                                    : "bg-slate-100 text-slate-600 hover:bg-slate-200"
                                    }`}
                            >
                                {tab.label} ({tab.count})
                            </button>
                        ))}
                    </div>
                </div>

                {/* Products Grid */}
                {filteredProducts.length === 0 ? (
                    <div className="bg-white rounded-xl p-12 text-center elevation-2">
                        <Package className="w-16 h-16 text-slate-300 mx-auto mb-4" />
                        <h3 className="text-xl font-bold text-slate-900 mb-2">
                            No Products Found
                        </h3>
                        <p className="text-slate-600 mb-6">
                            {filterStatus === "all"
                                ? "Start by creating your first product listing"
                                : `No ${filterStatus.replace("_", " ")} products`}
                        </p>
                        <button
                            onClick={() => router.push("/marketplace/sell/create")}
                            className="px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white font-semibold rounded-xl transition"
                        >
                            Create Product
                        </button>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                        {filteredProducts.map((product) => (
                            <div
                                key={product.id}
                                className="bg-white rounded-xl overflow-hidden elevation-2 hover:shadow-xl transition"
                            >
                                {/* Product Image */}
                                <div className="relative h-48 bg-slate-200">
                                    {product.images && product.images.length > 0 ? (
                                        <img
                                            src={product.images[0]}
                                            alt={product.title}
                                            className="w-full h-full object-cover"
                                        />
                                    ) : (
                                        <div className="flex items-center justify-center h-full">
                                            <Package className="w-12 h-12 text-slate-400" />
                                        </div>
                                    )}

                                    {/* Status Badge */}
                                    <div className="absolute top-3 right-3">
                                        <span className={`px-3 py-1 rounded-full text-xs font-bold ${product.status === "active" && product.availableQuantity > 0
                                            ? "bg-green-100 text-green-700"
                                            : product.availableQuantity === 0
                                                ? "bg-red-100 text-red-700"
                                                : "bg-slate-100 text-slate-900"
                                            }`}>
                                            {product.availableQuantity === 0 ? "Sold Out" : product.status}
                                        </span>
                                    </div>
                                </div>

                                {/* Product Info */}
                                <div className="p-5">
                                    <h3 className="text-lg font-bold text-slate-900 mb-2 line-clamp-1">
                                        {product.title}
                                    </h3>
                                    <p className="text-sm text-slate-600 mb-4 line-clamp-2">
                                        {product.description}
                                    </p>

                                    {/* Stats */}
                                    <div className="flex items-center gap-4 mb-4 text-sm text-slate-600">
                                        <div className="flex items-center gap-1">
                                            <Eye className="w-4 h-4" />
                                            <span>{product.views || 0}</span>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            <ShoppingCart className="w-4 h-4" />
                                            <span>{product.orders || 0}</span>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            <Star className="w-4 h-4 fill-yellow-500 text-yellow-500" />
                                            <span>{product.rating?.toFixed(1) || "0.0"}</span>
                                        </div>
                                    </div>

                                    {/* Price */}
                                    <div className="mb-4">
                                        <p className="text-2xl font-bold text-blue-600">
                                            ₦{product.pricingTiers[0]?.price.toLocaleString()}
                                            <span className="text-sm text-slate-500 font-normal">
                                                /{product.unit}
                                            </span>
                                        </p>
                                        <p className="text-xs text-slate-500">
                                            {product.availableQuantity} {product.unit}s available
                                        </p>
                                    </div>

                                    {/* Actions */}
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={() => router.push(`/marketplace/product/${product.id}`)}
                                            className="flex-1 px-4 py-2 bg-blue-100 hover:bg-blue-200 text-blue-700 font-semibold rounded-lg transition text-sm"
                                        >
                                            View
                                        </button>
                                        <button
                                            onClick={() => router.push(`/marketplace/sell/edit/${product.id}`)}
                                            className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-900 rounded-lg transition"
                                        >
                                            <Edit className="w-4 h-4" />
                                        </button>
                                        <button
                                            onClick={() => handleDeleteProduct(product.id, product.title)}
                                            className="px-4 py-2 bg-red-100 hover:bg-red-200 text-red-600 rounded-lg transition"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

/**
 * Village Market Event Detail Page
 * /marketplace/village-market/[id]
 *
 * Shows products and merchants for a specific event
 */

"use client";

import { useState, useEffect } from "react";
import { useParams, useRouter } from "next/navigation";
import Link from "next/link";
import {
    MapPin, Clock, Zap, Users, ExternalLink, ShoppingBag,
    ArrowLeft, Loader2, Camera,
} from "lucide-react";
import {
    getVillageMarketEventAction,
    joinVillageMarketEventAction,
    addFlashSaleProductAction,
} from "@/app/actions/village-market";
import type { VillageMarketEvent, FlashSaleProduct, ExternalMerchant } from "@/lib/types/marketplace";
import { useToast } from "@/contexts/ToastContext";
import { formatCurrency } from "@/lib/utils";

const fmtDate = (val: any) => {
    if (!val) return "—";
    const d = val?.toDate ? val.toDate() : new Date(val);
    return new Intl.DateTimeFormat("en-NG", { weekday: "long", day: "numeric", month: "long", hour: "2-digit", minute: "2-digit" }).format(d);
};

function isEventLive(event: VillageMarketEvent) {
    const now = new Date();
    const start = (event.startTime as any)?.toDate ? (event.startTime as any).toDate() : new Date(event.startTime as any);
    const end = (event.endTime as any)?.toDate ? (event.endTime as any).toDate() : new Date(event.endTime as any);
    return now >= start && now <= end;
}

export default function VillageMarketEventPage() {
    const params = useParams();
    const router = useRouter();
    const { showToast } = useToast();
    const eventId = params.id as string;

    const [event, setEvent] = useState<VillageMarketEvent | null>(null);
    const [products, setProducts] = useState<FlashSaleProduct[]>([]);
    const [loading, setLoading] = useState(true);
    const [joining, setJoining] = useState(false);
    const [showAddProduct, setShowAddProduct] = useState(false);
    const [addingProduct, setAddingProduct] = useState(false);
    const [productForm, setProductForm] = useState({ title: "", price: "", flashPrice: "", unit: "", availableQuantity: "" });

    async function loadEvent() {
        setLoading(true);
        const res = await getVillageMarketEventAction(eventId);
        setEvent(res.event);
        setProducts(res.products);
        setLoading(false);
    };

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => { loadEvent(); }, [eventId]);

    async function handleJoin() {
        setJoining(true);
        const res = await joinVillageMarketEventAction(eventId);
        setJoining(false);
        if (res.success) {
            showToast("You've joined this Village Market event!", "success");
            loadEvent();
        } else {
            showToast(res.error || "Failed to join event", "error");
        }
    };

    async function handleAddProduct() {
        if (!productForm.title || !productForm.price) return showToast("Title and price are required", "error");
        setAddingProduct(true);
        const res = await addFlashSaleProductAction({
            eventId,
            title: productForm.title,
            price: Number(productForm.price),
            flashPrice: productForm.flashPrice ? Number(productForm.flashPrice) : undefined,
            unit: productForm.unit || undefined,
            availableQuantity: productForm.availableQuantity ? Number(productForm.availableQuantity) : undefined,
        });
        setAddingProduct(false);
        if (res.success) {
            showToast("Product listed for this event!", "success");
            setShowAddProduct(false);
            setProductForm({ title: "", price: "", flashPrice: "", unit: "", availableQuantity: "" });
            loadEvent();
        } else {
            showToast(res.error || "Failed to add product", "error");
        }
    };

    if (loading) {
        return (
            <div className="min-h-screen bg-slate-50 flex items-center justify-center">
                <Loader2 className="w-10 h-10 animate-spin text-emerald-600" />
            </div>
        );
    }

    if (!event) {
        return (
            <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center gap-4">
                <p className="text-slate-500 text-lg">Event not found</p>
                <Link href="/marketplace/village-market" className="text-emerald-600 font-semibold hover:underline">← Back to Village Market</Link>
            </div>
        );
    }

    const live = isEventLive(event);

    return (
        <div className="min-h-screen bg-slate-50">
            {/* Header */}
            <div className={`relative overflow-hidden text-white ${live ? "bg-linear-to-br from-green-600 to-emerald-700" : "bg-linear-to-br from-slate-700 to-slate-800"}`}>
                <div className="max-w-5xl mx-auto px-6 py-10">
                    <Link href="/marketplace/village-market" className="inline-flex items-center gap-1.5 text-white/70 hover:text-white text-sm mb-6 transition">
                        <ArrowLeft className="w-4 h-4" /> Back to Village Market
                    </Link>

                    <div className="flex items-start justify-between gap-4 flex-wrap">
                        <div>
                            {live && (
                                <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-yellow-400 text-yellow-900 text-xs font-bold rounded-full mb-3 animate-pulse">
                                    <Zap className="w-3 h-3" /> LIVE NOW
                                </span>
                            )}
                            <h1 className="text-3xl font-extrabold mb-2">{event.title}</h1>
                            {event.description && <p className="text-white/80 max-w-xl">{event.description}</p>}
                        </div>
                        <button
                            onClick={handleJoin}
                            disabled={joining}
                            className="px-5 py-2.5 bg-white text-emerald-700 font-bold rounded-xl hover:bg-emerald-50 transition shadow flex items-center gap-2 shrink-0"
                        >
                            {joining ? <Loader2 className="w-4 h-4 animate-spin" /> : <Users className="w-4 h-4" />}
                            Join as Seller
                        </button>
                    </div>

                    <div className="flex flex-wrap gap-4 mt-6 text-white/80 text-sm">
                        <span className="flex items-center gap-1.5"><MapPin className="w-4 h-4" />{event.location}, {event.state}</span>
                        <span className="flex items-center gap-1.5"><Clock className="w-4 h-4" />{fmtDate(event.startTime)} — {fmtDate(event.endTime)}</span>
                        <span className="flex items-center gap-1.5"><Users className="w-4 h-4" />{event.participantSellerIds?.length || 0} sellers joined</span>
                    </div>
                </div>
            </div>

            <div className="max-w-5xl mx-auto px-6 py-8">
                {/* Add Product Banner */}
                <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 mb-8 flex items-center justify-between gap-4 flex-wrap">
                    <div>
                        <p className="font-semibold text-emerald-900">Are you participating in this event?</p>
                        <p className="text-sm text-emerald-700">List your products to appear in this flash sale.</p>
                    </div>
                    <button
                        onClick={() => setShowAddProduct(true)}
                        className="px-4 py-2 bg-emerald-600 text-white font-bold rounded-xl hover:bg-emerald-700 transition text-sm flex items-center gap-2"
                    >
                        <ShoppingBag className="w-4 h-4" /> Add Product
                    </button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Flash Sale Products */}
                    <div className="lg:col-span-2">
                        <h2 className="text-xl font-bold text-slate-900 mb-4">Flash Sale Products</h2>
                        {products.length === 0 ? (
                            <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center">
                                <ShoppingBag className="w-14 h-14 text-slate-300 mx-auto mb-3" />
                                <p className="text-slate-500">No products listed yet for this event</p>
                            </div>
                        ) : (
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                {products.map((p) => (
                                    <div key={p.id} className="bg-white rounded-xl border border-slate-200 overflow-hidden hover:shadow-md transition">
                                        <div className="h-36 bg-slate-100 flex items-center justify-center">
                                            {p.imageUrl ? (
                                                <img src={p.imageUrl} alt={p.title} className="w-full h-full object-cover" />
                                            ) : (
                                                <Camera className="w-10 h-10 text-slate-300" />
                                            )}
                                        </div>
                                        <div className="p-4">
                                            <h3 className="font-bold text-slate-900 text-sm mb-1 line-clamp-1">{p.title}</h3>
                                            <div className="flex items-center gap-2">
