"use client";

import { useEffect, useState } from "react";
import { Bell, X } from "lucide-react";
import type { Announcement } from "@/app/actions/cms";

export default function AnnouncementBanner() {
    const [announcements, setAnnouncements] = useState<Announcement[]>([]);
    const [dismissed, setDismissed] = useState<Set<string>>(new Set());

    useEffect(() => {
        // Load dismissed from localStorage
        const stored = localStorage.getItem("dismissed_announcements");
        if (stored) {
            setDismissed(new Set(JSON.parse(stored)));
        }

        // Mock announcements - in real app, fetch from API
        setAnnouncements([
            {
                id: "1",
                title: "Platform Maintenance Notice",
                content: "Scheduled maintenance on Sunday 3AM - 6AM WAT",
                type: "warning",
                targetAudience: "all",
                priority: "high",
                publishedAt: { seconds: Date.now() / 1000 } as any,
                createdBy: "admin",
                createdAt: { seconds: Date.now() / 1000 } as any,
                active: true,
            },
        ]);
    }, []);

    const handleDismiss = (id: string) => {
        const newDismissed = new Set(dismissed);
        newDismissed.add(id);
        setDismissed(newDismissed);
        localStorage.setItem("dismissed_announcements", JSON.stringify(Array.from(newDismissed)));
    };

    const visibleAnnouncements = announcements.filter(
        (a) => !dismissed.has(a.id || "")
    );

    if (visibleAnnouncements.length === 0) {
        return null;
    }

    const getTypeStyles = (type: string) => {
        const styles = {
            info: "bg-blue-50 border-blue-200",
            warning: "bg-amber-50 border-amber-200",
            success: "bg-emerald-50 border-emerald-200",
            emergency: "bg-red-50 border-red-200",
        };
        return styles[type as keyof typeof styles] || styles.info;
    };

    const getIconColor = (type: string) => {
        const colors = {
            info: "text-blue-600",
            warning: "text-amber-600",
            success: "text-emerald-600",
            emergency: "text-red-600",
        };
        return colors[type as keyof typeof colors] || colors.info;
    };

    return (
        <div className="space-y-2">
            {visibleAnnouncements.map((announcement) => (
                <div
                    key={announcement.id}
                    className={`border rounded-lg p-4 ${getTypeStyles(announcement.type)}`}
                >
                    <div className="flex items-start justify-between">
                        <div className="flex items-start space-x-3 flex-1">
                            <Bell className={`w-5 h-5 mt-0.5 ${getIconColor(announcement.type)}`} />
                            <div className="flex-1">
                                <h3 className="font-semibold text-slate-900">
                                    {announcement.title}
                                </h3>
                                <p className="text-sm text-slate-600 mt-1">
                                    {announcement.content}
                                </p>
                            </div>
                        </div>
                        <button
                            onClick={() => handleDismiss(announcement.id!)}
                            className="p-1 hover:bg-black/5 rounded transition"
                        >
                            <X className="w-5 h-5 text-slate-500" />
                        </button>
                    </div>
                </div>
            ))}
        </div>
    );
}

"use client";

import { Download, ShieldCheck } from "lucide-react";
import { useState } from "react";

interface DigitalIDCardProps {
    memberNumber: string;
    fullName: string;
    email: string;
    role: string;
    memberSince: Date;
    qrCodeDataUrl: string;
    expiresAt: Date;
}

export default function DigitalIDCard({
    memberNumber,
    fullName,
    email,
    role,
    memberSince,
    qrCodeDataUrl,
    expiresAt,
}: DigitalIDCardProps) {
    const [downloading, setDownloading] = useState(false);

    async function downloadAsPNG() {
        setDownloading(true);
        try {
            const cardElement = document.getElementById("digital-id-card");
            if (!cardElement) return;

            // Dynamically import heavy library only on click
            const html2canvas = (await import("html2canvas")).default;

            const canvas = await html2canvas(cardElement, {
                scale: 2,
                backgroundColor: null,
            });

            const link = document.createElement("a");
            link.download = `digital-id-${memberNumber}.png`;
            link.href = canvas.toDataURL();
            link.click();
        } catch (error) {
            console.error("Failed to download PNG:", error);
        } finally {
            setDownloading(false);
        }
    };

    async function downloadAsPDF() {
        setDownloading(true);
        try {
            const cardElement = document.getElementById("digital-id-card");
            if (!cardElement) return;

            // Dynamically import heavy libraries only on click
            const html2canvas = (await import("html2canvas")).default;
            const { jsPDF } = await import("jspdf");

            const canvas = await html2canvas(cardElement, {
                scale: 2,
                backgroundColor: "#ffffff",
            });

            const imgData = canvas.toDataURL("image/png");
            const pdf = new jsPDF({
                orientation: "landscape",
                unit: "px",
                format: [canvas.width, canvas.height],
            });

            pdf.addImage(imgData, "PNG", 0, 0, canvas.width, canvas.height);
            pdf.save(`digital-id-${memberNumber}.pdf`);
        } catch (error) {
            console.error("Failed to download PDF:", error);
        } finally {
            setDownloading(false);
        }
    };

    const roleColors = {
        member: "bg-blue-500",
        exporter: "bg-emerald-500",
        admin: "bg-purple-500",
        super_admin: "bg-red-500",
        vendor: "bg-amber-500",
    };

    const roleColor = roleColors[role as keyof typeof roleColors] || roleColors.member;

    return (
        <div className="space-y-6">
            {/* Digital ID Card */}
            <div
                id="digital-id-card"
                className="relative bg-linear-to-br from-blue-600 via-blue-700 to-indigo-800 rounded-2xl p-8 shadow-2xl max-w-2xl mx-auto"
            >
                {/* Header */}
                <div className="flex items-center justify-between mb-6">
                    <div className="flex items-center space-x-3">
                        <ShieldCheck className="w-8 h-8 text-white" />
                        <div>
                            <h2 className="text-white font-bold text-xl">Easy Sales Export</h2>
                            <p className="text-blue-200 text-sm">Digital Member ID</p>
                        </div>
                    </div>
                    <div className={`px-4 py-2 rounded-lg ${roleColor} text-white text-sm font-semibold uppercase`}>
                        {role.replace("_", " ")}
                    </div>
                </div>

                {/* Card Content */}
                <div className="grid grid-cols-3 gap-6">
                    {/* Member Info */}
                    <div className="col-span-2 space-y-4">
                        <div>
                            <p className="text-blue-200 text-sm mb-1">Member Number</p>
                            <p className="text-white font-mono text-2xl font-bold tracking-wider">
                                {memberNumber}
                            </p>
                        </div>

                        <div>
                            <p className="text-blue-200 text-sm mb-1">Full Name</p>
                            <p className="text-white text-xl font-semibold">{fullName}</p>
                        </div>

                        <div>
                            <p className="text-blue-200 text-sm mb-1">Email</p>
                            <p className="text-white text-sm">{email}</p>
                        </div>

                        <div className="grid grid-cols-2 gap-4 pt-4">
                            <div>
                                <p className="text-blue-200 text-xs mb-1">Member Since</p>
                                <p className="text-white text-sm font-medium">
                                    {new Date(memberSince).toLocaleDateString("en-GB", {
                                        day: "2-digit",
                                        month: "short",
                                        year: "numeric",
                                    })}
                                </p>
                            </div>
                            <div>
                                <p className="text-blue-200 text-xs mb-1">Valid Until</p>
                                <p className="text-white text-sm font-medium">
                                    {new Date(expiresAt).toLocaleDateString("en-GB", {
                                        day: "2-digit",
                                        month: "short",
                                        year: "numeric",
                                    })}
                                </p>
                            </div>
                        </div>
                    </div>

                    {/* QR Code */}
                    <div className="flex flex-col items-center justify-center bg-white rounded-xl p-4">
                        <img
                            src={qrCodeDataUrl}
                            alt="QR Code"
                            className="w-full h-auto"
                        />
                        <p className="text-xs text-gray-600 mt-2 text-center">
                            Scan to verify
                        </p>
                    </div>
                </div>

                {/* Footer */}
                <div className="mt-6 pt-4 border-t border-blue-500/30">
                    <p className="text-blue-200 text-xs text-center">
                        This digital ID is property of Easy Sales Export Platform (RC: 763845)
                    </p>
                </div>
            </div>

            {/* Download Buttons */}
            <div className="flex justify-center space-x-4">
                <button
                    onClick={downloadAsPNG}
                    disabled={downloading}
                    className="flex items-center space-x-2 px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-semibold transition disabled:opacity-50"
                >
                    <Download className="w-5 h-5" />
                    <span>Download PNG</span>
                </button>
                <button
                    onClick={downloadAsPDF}
                    disabled={downloading}
                    className="flex items-center space-x-2 px-6 py-3 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-semibold transition disabled:opacity-50"
                >
                    <Download className="w-5 h-5" />
                    <span>Download PDF</span>
                </button>
            </div>
        </div>
    );
}

